#include <stdio.h>
#define MAX_ENEMIES 4
typedef struct { int lane; int health; } Enemy;

int find_lane(const Enemy enemies[], int count, int lane) {
    for (int i = 0; i < count; i++) {
        if (enemies[i].lane == lane) {
            return i;
        }
    }
    return -1;
}

int main(void) {
    Enemy enemies[MAX_ENEMIES] = {{0, 30}, {2, 50}, {1, 40}};
    int count = 3;
    int hit = find_lane(enemies, count, 2);
    if (hit != -1) {
        enemies[hit].health -= 20;
        printf("enemy %d has %d health\n", hit, enemies[hit].health);
    }
    return 0;
}

