typedef struct {
    int health;
    int score;
} Player;

void reset(int* score) {
    *score = 0;
}

void heal(Player* p, int amount) {
    p->health = p->health + amount;
}

int main(void) {
    Player hero;
    hero.health = 60;
    hero.score = 99;
    reset(&hero.score);
    heal(&hero, 25);
    printf("health %d, score %d\n", hero.health, hero.score);
    return 0;
}

